/*
 * Minimal webextension-polyfill-compatible shim.
 * On Firefox MV3 `browser` is native (already promise-based) so this is a no-op.
 * On Chrome MV3 it wraps `chrome.*` callback APIs into the promise-based
 * `browser.*` interface expected by the extension, giving Firefox/Chrome parity.
 */
(function () {
  if (typeof globalThis.browser !== 'undefined') return;
  if (typeof globalThis.chrome === 'undefined') return;

  function promisify(fn) {
    return function () {
      var args = Array.prototype.slice.call(arguments);
      return new Promise(function (resolve, reject) {
        try {
          args.push(function () {
            var err = globalThis.chrome.runtime.lastError;
            if (err) reject(err);
            else resolve(arguments[0]);
          });
          fn.apply(null, args);
        } catch (e) {
          reject(e);
        }
      });
    };
  }

  var b = {
    runtime: {
      id: globalThis.chrome.runtime ? globalThis.chrome.runtime.id : undefined,
      sendMessage: function (msg) {
        return new Promise(function (resolve, reject) {
          try {
            globalThis.chrome.runtime.sendMessage(msg, function (r) {
              var err = globalThis.chrome.runtime.lastError;
              if (err) reject(err);
              else resolve(r);
            });
          } catch (e) {
            reject(e);
          }
        });
      },
      onMessage: {
        addListener: function (l) {
          if (globalThis.chrome.runtime && globalThis.chrome.runtime.onMessage) {
            globalThis.chrome.runtime.onMessage.addListener(l);
          }
        }
      }
    }
  };

  if (globalThis.chrome.storage && globalThis.chrome.storage.local) {
    b.storage = {
      local: {
        get: promisify(globalThis.chrome.storage.local.get),
        set: promisify(globalThis.chrome.storage.local.set),
        remove: promisify(globalThis.chrome.storage.local.remove),
        getBytesInUse: globalThis.chrome.storage.local.getBytesInUse
          ? promisify(globalThis.chrome.storage.local.getBytesInUse)
          : null
      }
    };
  }

  globalThis.browser = b;
})();
